    // 与 vendored useFloatingLauncher 的存储键逐字一致（storagePrefix + 'quick-action.position.v1'）。
    const QUICK_ENHANCER_POSITION_KEY = 'dsh-research-kit.promptkit.quick-action.position.v1'
