    const DEPOSIT_BUTTON_GAP = 8
    // vendored 的拖拽钳制范围（左上角坐标）：x ∈ [16, width-62]，y ∈ [58, height-62]。
    const CLAMP_MIN_X = 16
    const CLAMP_MAX_INSET_X = 62
    const CLAMP_MIN_Y = 58
    const CLAMP_MAX_INSET_Y = 62

